"""Primitive equations for actual lines, including verticals, alternate rhombus labellings and medians."""
import argparse
import json
from fractions import Fraction as F
from functools import reduce
from itertools import combinations, permutations
from math import gcd, lcm
from coordinate_actions import show
from coordinate_curves import curve_lesson, graph
