OUT=ROOT/'geometry-course/textbook/data/coordinate-lines.json'


def line(p,q):
    x,y=p;u,v=q;raw=[F(y-v),F(u-x),F(x*v-u*y)];den=reduce(lcm,(t.denominator for t in raw));ints=[int(t*den) for t in raw]
    d=reduce(gcd,map(abs,ints));assert d
    if next(k for k in ints if k)<0:d=-d
    return tuple(k//d for k in ints)


def text(eq):
    terms=[]
    for k,v in zip(eq,('x','y',''),strict=True):
        if not k:continue
        sign='−' if k<0 else '+' if terms else ''
        terms.append(sign+('' if abs(k)==1 and v else str(abs(k)))+v)
    return ''.join(terms)+'=0'


def section(eq,vertices):
    a,b,c=eq;xs=[0]+[p[0] for p in vertices.values()];ys=[0]+[p[1] for p in vertices.values()]
    lo,hi=min(xs)-2,max(xs)+2;down,up=min(ys)-2,max(ys)+2;hits=[]
    if b:
        for x in (lo,hi):
            y=-(a*x+c)/b
            if down<=y<=up:hits.append((x,y))
    if a:
        for y in (down,up):
            x=-(b*y+c)/a
            if lo<=x<=hi:hits.append((x,y))
    return max(combinations(dict.fromkeys(hits),2),key=lambda pair:sum((x-y)**2 for x,y in zip(*pair,strict=True)))


def draw(label,vertices,lines=(),edges=()):
    return graph(label,vertices,edges=edges,lines=[section(e,vertices) for e in lines])


def finish(card,eq):
    a,b,c=eq
    card['answer']=dict(mode='exact',accepted=[text(eq),text(eq).replace('−','-'),f'{a};{b};{c}',f'{a}; {b}; {c}'],prompt='Введи уравнение в сокращённом виде Ax+By+C=0 без пробелов либо тройку A;B;C. Коэффициенты целые без общего делителя; первый ненулевой положителен.',feedback='Подставь обе точки в Ax+By+C. Если обе суммы нулевые, ещё сократи общий множитель и выбери положительный первый коэффициент.')
    return card


def pair_set(card,first,second):
    accepted=[]
    for a,b in permutations([first,second]):
        x=';'.join(map(str,a));y=';'.join(map(str,b))
        accepted.extend([x+' | '+y,x+'|'+y,text(a)+'; '+text(b),text(a)+';'+text(b)])
    card['answer']=dict(mode='exact',accepted=accepted,prompt='Введи обе тройки коэффициентов как A;B;C | A;B;C. Для каждой сократи общий множитель и сделай первый ненулевой коэффициент положительным. Порядок прямых свободный.',feedback='Проверь каждую прямую по двум её точкам. Для горизонтальной и вертикальной прямых один из коэффициентов равен нулю; сохрани его в тройке.')
    return card


def make(n,**content):
    card=curve_lesson(n,**content);card['help'][1].update(theoryIds=['atanasyan-7-9-theory-99-part-1'],text='Прямая имеет уравнение Ax+By+C=0, где A и B не оба нулевые. Подстановка любой из определяющих точек даёт ноль.')
    card['visualization']['caption']='Одна клетка сетки равна единице. Сверь каждую отмеченную точку и положение всей прямой.';card['visualization']['model']['description']=card['visualization']['caption'];card['review']['reviewer']='Атанасян 7–9, 2023, печатные с. 264–265 и ключ на с. 398. Сверены точки, середины и все коэффициенты; каждая прямая независимо проверена по изображённым точкам.'
    return card


def two_points():
    entries=[('а','AB',(1,-1),(-3,2),(1,2),(1,-3)),('б','CD',(2,5),(5,2),(-2,3),(4,3)),('в','MN',(0,1),(-4,-5),(0,-1),(2,3))]
    rows=[]
    for part,names,p,q,u,v in entries:
        a,b=names;src={a:p,b:q};pts={'U':u,'V':v};eq=line(p,q);other=line(u,v);dx=q[0]-p[0];dy=q[1]-p[1]
        read=draw('Две точки определяют прямую',src);direction=draw('Сравни изменения координат',src,edges=[(a,b)]);full=draw('Продли отрезок в обе стороны',src,[eq]);fresh=draw('Проверь прямую через новые точки',pts,[other]);
        newrule=('Обе абсциссы равны 1. Это вертикальная прямая x=1; делить на разность абсцисс здесь нельзя.' if part=='а' else 'Обе ординаты равны 3, значит прямая горизонтальна и задаётся равенством y=3.' if part=='б' else 'Смещение равно (2;4), за единицу по x ордината увеличивается на 2. При x=0 имеем y=−1, поэтому y=2x−1.')
        card=make(1058,part=part,pages=[264,265] if part=='а' else [264],question=f'Построй прямую через {a}={show(p)} и {b}={show(q)} и запиши её уравнение. Покажи подстановкой, что оно подходит для обеих точек.',answer=f'{text(eq)}. В обеих исходных точках левая часть равна нулю. Умножение всех трёх коэффициентов на одно и то же ненулевое число даёт ту же прямую.',hint='Используй (y−y₁)(x₂−x₁)=(x−x₁)(y₂−y₁). В такой записи не приходится делить на величину, которая может оказаться нулём.',steps=[('Найди направление',f'Вектор от {a} к {b} имеет координаты ({dx};{dy}). Поэтому для точки (x;y) этой прямой верно ({dx})(y−({p[1]}))=({dy})(x−({p[0]})).','Параллельные смещения дают равные произведения координат крест-накрест.'),('Приведи к общей форме',f'Раскрой скобки и собери члены: {text(eq)}. Проверка: для {a} получается {eq[0]}·({p[0]})+({eq[1]})·({p[1]})+({eq[2]})=0, для {b} — {eq[0]}·({q[0]})+({eq[1]})·({q[1]})+({eq[2]})=0.','Две различные точки определяют единственную прямую.'),('Испытай другой наклон',f'Новые U={show(u)}, V={show(v)}. {newrule} Сокращённая общая форма: {text(other)}.','Один способ построения должен охватывать как наклонные, так и осевые прямые.')],frames=[read,direction,full,fresh],cases=[direction,full,fresh],prompts=[(f'Чему равно подписанное изменение y при переходе от {a} к {b}?',str(dy),'Вычти начальную ординату из конечной.'),('Чему равен свободный член C нового сокращённого уравнения Ax+By+C=0 при положительном первом коэффициенте?',str(other[2]),newrule)])
        rows.append(finish(card,eq))
    return rows


def midpoint(p,q):return tuple(F(a+b,2) for a,b in zip(p,q,strict=True))


def median():
    src={'A':(4,6),'B':(-4,0),'C':(-1,-4)};m=midpoint(src['A'],src['B']);allpts={**src,'M':m};eq=line(src['C'],m)
    edges=[('A','B'),('B','C'),('C','A')];new={'A':(2,0),'B':(4,4),'C':(-1,2),'M':(3,2)};fresh=line(new['C'],new['M']);
    neutral=draw('Исходный треугольник',src,edges=edges);half=draw('Найди середину AB',allpts,edges=edges+[('C','M')]);full=draw('Прямая медианы CM',allpts,[eq],edges);variant=draw('Новый треугольник и его медиана',new,[fresh],edges)
    card=make(1059,pages=[265],question='Даны A=(4;6), B=(−4;0), C=(−1;−4). Запиши уравнение прямой, на которой лежит медиана CM треугольника ABC.',answer='M=(0;3). Смещение от C до M равно (1;7). Следовательно, y=7x+3, или 7x−y+3=0.',hint='Ищи середину стороны AB: медиана из C проходит именно через эту точку, а не обязательно через начало координат.',steps=[('Вычисли M','Средние арифметические координат A и B равны (4−4)/2=0 и (6+0)/2=3. Получаем M=(0;3).','Медиана соединяет вершину с серединой противоположной стороны.'),('Проведи всю прямую','Смещение CM=(1;7) даёт угловой коэффициент 7. При x=0 прямая имеет y=3. В 7x−y+3=0 входят и C, и M.','Условие о медиане сначала задаёт точку, через которую проходит искомая прямая.'),('Измени треугольник','Пусть A=(2;0), B=(4;4), C=(−1;2). Тогда M=(3;2); у C и M одинаковая ордината, так что новая прямая горизонтальна: y−2=0.','После изменения вершин середину вычисляют заново.')],frames=[neutral,half,full,variant],cases=[half,full,variant],prompts=[('Чему равна ордината исходной середины AB?','3','Возьми среднее 6 и 0.'),('Какова ордината любой точки новой прямой медианы?','2','Одинаковые ординаты C и M задают горизонталь.')]);return finish(card,eq)


def trapezoids():
    src={'A':(-2,-2),'B':(-3,1),'C':(7,7),'D':(3,1)};other={'A':(0,0),'B':(-2,2),'C':(4,5),'D':(2,1)};edges=[('A','B'),('B','C'),('C','D'),('D','A')]
    def mids(p):return {**p,'M':midpoint(p['A'],p['B']),'N':midpoint(p['C'],p['D'])}
    source=mids(src);third=mids(other);ac=line(src['A'],src['C']);bd=line(src['B'],src['D']);nac=line(third['A'],third['C']);nbd=line(third['B'],third['D']);mn=line(source['M'],source['N']);newmn=line(third['M'],third['N']);
    first=draw('Трапеция и четыре заданные вершины',src,edges=edges);a1=draw('Проверь диагональ AC',src,[ac],edges);a2=draw('Сравни обе диагонали',src,[ac,bd],edges);a3=draw('Диагонали изменённой трапеции',other,[nac,nbd],edges)
    a=make(1060,part='а',pages=[265],question='У трапеции A=(−2;−2), B=(−3;1), C=(7;7), D=(3;1). Найди уравнения обеих прямых, содержащих её диагонали.',answer='Для AC получаем x−y=0. Для BD у обеих точек y=1, и уравнение этой прямой y−1=0.',hint='Диагонали соединяют несоседние вершины. Проверь пары A,C и B,D отдельно.',steps=[('Найди AC','У A и C каждая ордината равна соответствующей абсциссе. Обе лежат на y=x. В общей форме получается x−y=0.','Две различные точки однозначно задают прямую.'),('Найди BD','У B=(−3;1) и D=(3;1) совпадают ординаты. Прямая горизонтальна, и её уравнение y−1=0. Для первой диагонали оно не подходит.','Для горизонтальной линии в общей форме отсутствует член с x.'),('Проверь другие диагонали','В новой трапеции A=(0;0), B=(−2;2), C=(4;5), D=(2;1). Получаем 5x−4y=0 для AC и x+4y−6=0 для BD. Подставь обе пары.','После сдвига одной вершины не считай диагональ горизонтальной без проверки.')],frames=[first,a1,a2,a3],cases=[a1,a2,a3],prompts=[('Чему равна ордината всех точек исходной BD?','1','Сравни вторые координаты B и D.'),('В новом уравнении BD при A=1, B=4 чему равен свободный коэффициент C?','-6','Для B=(−2;2) сумма x+4y равна 6.')]);pair_set(a,ac,bd)
    b1=draw('Середины именно боковых сторон',source,edges=edges+[('M','N')]);b2=draw('Прямая средней линии',source,[mn],edges);b3=draw('Новые середины и их прямая',third,[newmn],edges)
    b=make(1060,part='б',pages=[265],question='Для той же трапеции A=(−2;−2), B=(−3;1), C=(7;7), D=(3;1) найди уравнение прямой, содержащей среднюю линию. Укажи, какие две стороны ты делишь пополам.',answer='Основания AD и BC параллельны. Середины боковых сторон AB и CD равны M=(−5/2;−1/2), N=(5;4). Через них проходит 3x−5y+5=0.',hint='Не бери середины диагоналей. У исходных оснований AD=(5;3) и BC=(10;6) направления совпадают.',steps=[('Отдели основания от боковых сторон','AD=(5;3), BC=(10;6), поэтому это основания. Нужны середины других сторон: AB и CD. Получаем M=(−5/2;−1/2), N=(5;4).','Средняя линия трапеции соединяет середины боковых сторон.'),('Составь уравнение прямой','Направление средней линии параллельно (5;3). Поэтому в общей форме можно взять A=3, B=−5. Подстановка N даёт 15−20+C=0, то есть C=5. Точка M тоже удовлетворяет 3x−5y+5=0.','Параллельность задаёт направление; точка задаёт положение линии.'),('Проверь другую трапецию','Для A=(0;0), B=(−2;2), C=(4;5), D=(2;1) середины боковых сторон равны (−1;1) и (3;3). Их прямая x−2y+3=0 параллельна обоим основаниям.','Проверяй принадлежность обеих середин, даже если направление уже известно.')],frames=[first,b1,b2,b3],cases=[b1,b2,b3],prompts=[('Какова абсцисса N, середины CD, в исходной задаче?','5','Найди среднее 7 и 3.'),('В новом уравнении для средней линии при A=1, B=−2 найди C.','3','Подставь найденную новую середину (−1;1): −1−2+C=0.')]);return [a,finish(b,mn)]


def parallels():
    m=(2,5);pts={'M':m,'P':(5,5),'Q':(2,1)};up=(1,0,-2);right=(0,1,-5);other={'T':(-3,-1),'P':(1,-1),'Q':(-3,3)};u=(1,0,3);v=(0,1,1)
    initial=draw('Заданная точка M',{'M':m});first=draw('Через M параллельно Ox',pts,[right]);both=draw('Две осевые прямые через M',pts,[right,up]);fresh=draw('Поставь другую общую точку',other,[u,v]);
    card=make(1061,pages=[265],question='Через M=(2;5) проведи обе прямые, параллельные координатным осям. Запиши уравнения и поясни, какая координата остаётся постоянной.',answer='Параллельная оси Ox прямая задаётся y=5. Параллельная оси Oy прямая задаётся x=2. Они пересекаются в M.',hint='При движении вправо или влево меняется x; при вертикальном движении меняется y.',steps=[('Сохрани ординату','Параллельно Ox можно идти от (2;5) к (5;5): обе точки имеют y=5. Уравнение всей горизонтальной прямой y−5=0.','У горизонтальной прямой постоянно значение y.'),('Сохрани абсциссу','Параллельно Oy можно идти от M к (2;1): у всей вертикали x=2. Уравнение x−2=0. Обе прямые содержат M.','У вертикальной прямой постоянна первая координата.'),('Измени точку пересечения','Пусть T=(−3;−1). Новые вертикаль x=−3 и горизонталь y=−1 пересекаются в T. Здесь отрицательны обе фиксированные координаты.','Положение осевых прямых задаётся соответствующей координатой одной точки.')],frames=[initial,first,both,fresh],cases=[first,both,fresh],prompts=[('Какова постоянная ордината прямой через M, параллельной Ox?','5','У горизонтали не меняется вторая координата.'),('Какая абсцисса у любой точки новой вертикали через T?','-3','У вертикали сохраняется первая координата T.')]);return pair_set(card,up,right)


def graph_axes():
    rows=[]
    for part,axis,value,next_value in [('а','y',3,-2),('б','x',-2,3),('в','y',-4,1),('г','x',7,-1)]:
        j=0 if axis=='x' else 1;motion='вертикальная' if j==0 else 'горизонтальная';parallel='Oy' if j==0 else 'Ox';unused='y' if j==0 else 'x';side=('справа' if value>0 else 'слева') if j==0 else ('выше' if value>0 else 'ниже')
        newaxis=unused; makep=lambda a,t,v:(v,t) if a=='x' else (t,v)
        pts={'A':makep(axis,-2,value),'B':makep(axis,2,value)};new={'P':makep(newaxis,-2,next_value),'Q':makep(newaxis,2,next_value)};eq=line(pts['A'],pts['B']);second=line(new['P'],new['Q']);
        read=draw('Отметь одно известное положение',{'A':pts['A']});two=draw('Две точки с общей координатой',pts,edges=[('A','B')]);full=draw('Продли полученную прямую',pts,[eq]);variant=draw('Теперь фиксирована другая координата',new,[second]);
        card=make(1062,part=part,pages=[265],question=f'Построй прямую {axis}={value} на координатной плоскости. Отметь две её точки, укажи ось, которой прямая параллельна, и проверь построение.',answer=f'Например, A={show(pts["A"])}, B={show(pts["B"])}. Через них проходит {motion} прямая, параллельная {parallel}. Она расположена {side} от нулевого значения координаты {axis}.',hint=f'Оставляй {axis}={value}, а вторую координату выбирай произвольно. Отметь хотя бы две различные точки.',steps=[('Выбери две точки',f'Назначь {unused}=−2 и {unused}=2, оставляя {axis}={value}. Получатся {show(pts["A"])} и {show(pts["B"])}.','Для всей прямой одна координата фиксирована, другая свободна.'),('Продли и проверь',f'Соедини отмеченные точки и продли линию в обе стороны. Вся она параллельна оси {parallel}. На ней каждая точка имеет {axis}={value}, а выбрав точку с другим значением {axis}, получим точку вне линии.','Уравнение задаёт всю неограниченную прямую, а не один отрезок.'),('Смени фиксированную координату',f'Теперь построй {newaxis}={next_value} по P={show(new["P"])}, Q={show(new["Q"])}. Фиксируется уже другая координата, поэтому направление меняется на перпендикулярное.','По одной букве в уравнении нельзя называть ось параллельности: сначала выясни, какая координата остаётся свободной.')],frames=[read,two,full,variant],cases=[two,full,variant],prompts=[(f'Какое значение {axis} должно быть у всех исходных точек?',str(value),'Прочти заданную постоянную вместе со знаком.'),(f'Какое значение {newaxis} имеют обе новые точки P и Q?',str(next_value),'Возьми фиксированную координату нового уравнения.')]);
        card['answer']=dict(mode='exact',accepted=[parallel,parallel.lower(),parallel.upper(),'О'+('у' if j==0 else 'х'),'о'+('у' if j==0 else 'х'),'О'+('У' if j==0 else 'Х'),'ось '+parallel,'оси '+parallel],prompt='После построения укажи обозначение оси, которой параллельна твоя прямая: Ox или Oy.',feedback=f'От одной отмеченной точки к другой меняется {unused}, а {axis}={value} остаётся неизменным. Сопоставь направление с осями.');rows.append(card)
    return rows


def missing_y():
    src={'A':(-8,-6),'B':(-3,-1)};eq=line(src['A'],src['B']);allpts={**src,'M':(5,7)};other={'A':(0,2),'B':(2,-2),'M':(-1,4)};eq2=line(other['A'],other['B']);initial=draw('Две заданные точки A и B',src);direction=draw('Найди изменение на единицу x',src,[eq]);full=draw('Пересечение с вертикалью x=5',allpts,[eq,(1,0,-5)]);fresh=draw('Другая прямая и другая абсцисса',other,[eq2,(1,0,1)]);
    card=make(1063,pages=[265],question='Прямая AB проходит через A=(−8;−6), B=(−3;−1). Найди ординату M, если M лежит на этой прямой и её абсцисса равна 5.',answer='При переходе от A к B изменения x и y равны 5. Поэтому y=x+2. Для x=5 получаем y=7 и M=(5;7).',hint='Сначала найди зависимость координат на всей прямой. Точка M может находиться за пределами исходного отрезка AB.',steps=[('Определи наклон','От A до B координаты увеличиваются на 5 каждая. При увеличении x на 1 значение y увеличивается на 1. У A разность y−x равна 2, поэтому уравнение y=x+2.','Наклон постоянен на всей прямой.'),('Подставь абсциссу M','При x=5 получаем y=5+2=7. Прямая AB пересекает вертикаль x=5 в M=(5;7). Эта точка лежит на продолжении за B.','Уравнение прямой относится ко всем её точкам.'),('Измени наклон','В новом примере A=(0;2), B=(2;−2). На единицу x ордината уменьшается на 2, поэтому y=−2x+2. При x=−1 получается y=4.','Увеличение x на положительное число может уменьшать y.')],frames=[initial,direction,full,fresh],cases=[direction,full,fresh],prompts=[('Найди подписанное изменение y от A к B в исходной задаче.','5','Вычти −6 из −1.'),('Для новой прямой чему равно y при x=−1?','4','Подставь −1 в y=−2x+2.')]);card['answer']=dict(mode='exact',accepted=['7','7,0','7.0','y=7','y = 7'],prompt='Введи ординату точки M.',feedback='У исходной прямой y−x=2. К заданной абсциссе 5 прибавь 2.');return card


def rhombus():
    def diamond(a,b):
        p={'A':(a,0),'B':(0,b),'C':(-a,0),'D':(0,-b)};edges=[('A','B'),('B','C'),('C','D'),('D','A')]
        return p,edges,[line(p[x],p[y]) for x,y in edges]
    src,e,lines=diamond(5,2);swap,_,alt=diamond(2,5);fresh,_,other=diamond(3,2)
    neutral=draw('Полудиагонали задают вершины',src,edges=e+[('A','C'),('B','D')]);first=draw('Сторона в первой четверти',src,[lines[0]],e);allfour=draw('Все стороны при длинной диагонали на Ox',src,lines,e);turned=draw('Длинная диагональ на Oy',swap,alt,e);new=draw('Измени длину горизонтальной диагонали',fresh,other,e)
    card=make(1064,pages=[265],question='Диагонали ромба равны 10 см и 4 см и лежат на координатных осях. Найди прямые, содержащие четыре стороны, измеряя координаты в сантиметрах. Проверь оба допустимых назначения длин осям.',answer='При полудиагоналях 5 на Ox и 2 на Oy получаем четыре прямые 2x+5y=10, 2x−5y=10, 2x+5y=−10 и 2x−5y=−10. Если длинная диагональ лежит на Oy, меняются местами коэффициенты 2 и 5: получаем 5x±2y=±10 с независимыми знаками.',hint='Диагонали ромба делятся точкой пересечения пополам. На осях отмечаются полуоси длины 5 и 2, а не исходные 10 и 4.',steps=[('Восстанови четыре вершины','Оси пересекаются в O и содержат диагонали, поэтому O — их общая середина. Если длинная диагональ на Ox, вершины (5;0), (0;2), (−5;0), (0;−2). Прямая первой стороны имеет пересечения (5;0) и (0;2), значит 2x+5y=10.','По двум точкам на осях удобно написать уравнение в отрезках x/5+y/2=1.'),('Отрази сторону и поменяй оси','Отражение относительно каждой оси меняет соответствующий знак. Получаются четыре прямые 2x±5y=±10 с независимыми знаками. При обмене осями вершины (2;0), (0;5), (−2;0), (0;−5), и тогда 5x±2y=±10.','В условии не указано, какой оси принадлежит длинная диагональ.'),('Проверь другой ромб','У нового ромба с горизонтальной диагональю 6 и вертикальной 4 полуоси 3 и 2. Прямая в первой четверти имеет уравнение 2x+3y=6. Остальные три получаются теми же отражениями.','Пересечения этих прямых с осями — вершины ромба, по ним проверяются уравнения сторон.')],frames=[neutral,first,allfour,new],cases=[first,allfour,turned,new],prompts=[('Какова абсцисса правой вершины при горизонтальной диагонали длиной 10?','5','Точка O делит диагональ пополам.'),('Для нового ромба чему равна правая часть 2x+3y=K на стороне в первой четверти?','6','Подставь вершину (3;0) или (0;2).')]);card['answer']=dict(mode='exact',accepted=['2;5;10','2; 5; 10','2x±5y=±10'],prompt='Для горизонтальной диагонали 10 заверши семейство четырёх уравнений Ax±By=±K с независимыми знаками. Введи положительные A;B;K без общего множителя.',feedback='Проверь положительные вершины (5;0), (0;2). Для стороны первой четверти нужны 5A=2B=K. Используй наименьшие целые A и B.');return card


def build():return {'bookId':BOOK,'lessons':two_points()+[median()]+trapezoids()+[parallels()]+graph_axes()+[missing_y(),rhombus()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');opts=parser.parse_args();s=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if opts.check:assert OUT.read_text()==s
    else:OUT.write_text(s)
